# Sourced only by run-local.sh: all IDs are generated by private fixtures.
location_admin=$(psql_local canonical_integration -qAtc "insert into auth.users(id) values(gen_random_uuid()) returning id")
location_low=$(psql_local canonical_integration -qAtc "insert into public.local_jobs(title,company,location,origin,active,admin_hidden) values('concurrency fixture','Concurrency company','Concurrent address','crawler',false,false) returning id")
location_high=$(psql_local canonical_integration -qAtc "insert into public.local_jobs(title,company,location,origin,active,admin_hidden) values('concurrency fixture','Concurrency company','Concurrent address','crawler',false,false) returning id")
psql_local canonical_integration -qc "select public.replace_job_work_locations($location_low,'[{\"raw_address\":\"Concurrent address\"}]');select public.replace_job_work_locations($location_high,'[{\"raw_address\":\"Concurrent address\"}]');" >/dev/null
location_candidate=$(psql_local canonical_integration -qAtc "insert into public.job_location_candidates(job_id,company_snapshot,address_snapshot,lat,lng,place_precision,source,evidence) values($location_low,'Concurrency company','Concurrent address',21.4,106.4,'building','company_official','Concurrent official evidence') returning id")
# Process A acquires the actual shared entry gate and holds its transaction;
# B begins the competing real RPC while A is still open. No table EXCLUSIVE lock.
concurrent_pair() {
 local pair_name=$1 first_statement=$2 second_statement=$3
 psql_local canonical_integration > "$location_logs/$pair_name-a.log" 2>&1 <<SQL &
begin;
set local statement_timeout='8s';
select set_config('request.jwt.claim.sub','$location_admin',true);
select set_config('request.jwt.claims','{"app_metadata":{"role":"admin"}}',true);
$first_statement
\echo FIRST_MUTATION_HELD
select pg_sleep(0.7);
commit;
SQL
 local first_pid=$!
 for attempt in $(seq 1 100);do if rg -q FIRST_MUTATION_HELD "$location_logs/$pair_name-a.log";then break;fi;sleep 0.02;done
 psql_local canonical_integration > "$location_logs/$pair_name-b.log" 2>&1 <<SQL &
begin;
set local statement_timeout='8s';
select set_config('request.jwt.claim.sub','$location_admin',true);
select set_config('request.jwt.claims','{"app_metadata":{"role":"admin"}}',true);
$second_statement
commit;
SQL
 local second_pid=$!
 if ! wait "$first_pid";then cat "$location_logs/$pair_name-a.log";return 1;fi
 if ! wait "$second_pid";then cat "$location_logs/$pair_name-b.log";return 1;fi
 if rg -qi 'deadlock|ERROR' "$location_logs/$pair_name-a.log" "$location_logs/$pair_name-b.log";then cat "$location_logs/$pair_name-a.log" "$location_logs/$pair_name-b.log";return 1;fi
 echo "PASS: concurrent $pair_name"
}
location_lease=$(psql_local canonical_integration -qAtc "update public.map_r1_location_jobs set state='processing',snapshot=public.map_r1_snapshot(job_id),lease=gen_random_uuid() where job_id=$location_low returning lease")
concurrent_pair approval-vs-completion "select public.admin_review_location_candidate($location_candidate,'approve','race');" "select public.map_r1_complete($location_low,'$location_lease',jsonb_build_object('kind','area','address','Concurrent address','lat',22,'lng',105,'source','provider','checkedAt',now()));"
[ "$(psql_local canonical_integration -qAtc "select bool_and(lat=21.4 and location_verified) from public.job_work_locations where job_id in ($location_low,$location_high)")" = t ]
# Historical deadlock shape: low-ID approval fanout vs high-ID parent edit.
concurrent_pair approval-vs-high-parent "select public.admin_review_location_candidate($location_candidate,'revoke','prepare change');" "update public.local_jobs set location='Changed concurrent address' where id=$location_high;"
concurrent_pair same-company-parent-edits "update public.local_jobs set location='Low parent changed' where id=$location_low;" "update public.local_jobs set location='High parent changed again' where id=$location_high;"
# Real reserve_call starts with SELECT FOR UPDATE. It must gate before this lock.
location_lease=$(psql_local canonical_integration -qAtc "update public.map_r1_location_jobs set state='processing',snapshot=public.map_r1_snapshot(job_id),search_key='concurrent-budget',calls=0,lease=gen_random_uuid() where job_id=$location_low returning lease")
psql_local canonical_integration -qc "insert into public.map_r1_search_history(job_id,search_key,search_input) values($location_low,'concurrent-budget','{}') on conflict do nothing" >/dev/null
concurrent_pair parent-vs-reserve "update public.local_jobs set company='Concurrency company renamed' where id=$location_high;" "select public.map_r1_reserve_call($location_low,'$location_lease');"
# Actual claim helpers and budget/reservation limits retain their semantics.
psql_local canonical_integration -qc "update public.map_r1_location_jobs set updated_at=now()-interval '2 hours',state='failed',failures=0,calls=0,lease=null where job_id=$location_low" >/dev/null
location_lease=$(psql_local canonical_integration -qAtc "select gen_random_uuid()")
concurrent_pair parent-vs-claim "update public.local_jobs set company='Concurrency company newest' where id=$location_high;" "select * from public.map_r1_claim_job_v2($location_low,'$location_lease',true);"
[ "$(psql_local canonical_integration -qAtc 'select count(*) from public.location_integrity_issues()')" = 0 ]
# Every actual queue entry was patched before its first row-locking statement.
[ "$(psql_local canonical_integration -qAtc "select count(*) from pg_proc where proname in ('map_r1_claim_job','map_r1_claim_job_v2','map_r1_claim_batch','map_r1_reserve_call') and prosrc ~ 'PERFORM pg_catalog.pg_advisory_xact_lock\\(20261026,27\\)'")" = 4 ]
